// Cat Client — XHTTP relay for Vercel (Node.js runtime). Generated by the Cat Client app.
// It forwards ONLY requests under the configured XHTTP path to your own Xray server and streams
// the answer back unchanged. Every other path gets a small static page, so the project is not an
// open proxy. Licence: GPL-3.0 (Cat Client).
import http from 'node:http';
import https from 'node:https';

const UP = /*CAT_UPSTREAM*/{"proto":"https","connect":"example.com","port":443,"servername":"example.com","host":"example.com","insecure":false,"path":"/"}/*END*/;

const DROP_REQ = new Set(['host', 'connection', 'keep-alive', 'proxy-connection', 'proxy-authorization',
  'te', 'trailer', 'transfer-encoding', 'upgrade', 'forwarded', 'x-real-ip', 'x-forwarded-for',
  'x-forwarded-host', 'x-forwarded-proto', 'x-forwarded-port', 'accept-encoding']);
const DROP_RES = new Set(['connection', 'keep-alive', 'transfer-encoding']);

function guarded(url) {
  const base = UP.path.endsWith('/') ? UP.path.slice(0, -1) : UP.path;
  if (!base) return true;
  return url === base || url.startsWith(base + '/') || url.startsWith(base + '?');
}

function page(res) {
  res.statusCode = 200;
  res.setHeader('content-type', 'text/html; charset=utf-8');
  res.setHeader('cache-control', 'public, max-age=3600');
  res.end('<!doctype html><title>Notes</title><p>Nothing to see here.</p>');
}

export default function handler(req, res) {
  const url = req.url || '/';
  if (!guarded(url)) return page(res);

  const headers = {};
  for (const [k, v] of Object.entries(req.headers)) {
    const key = k.toLowerCase();
    if (DROP_REQ.has(key) || key.startsWith('x-vercel-')) continue;
    headers[key] = v;
  }
  headers.host = UP.host;

  const secure = UP.proto === 'https';
  const options = {
    host: UP.connect,
    port: UP.port,
    method: req.method,
    path: url,
    headers,
  };
  if (secure) {
    options.servername = UP.servername;
    options.rejectUnauthorized = !UP.insecure;
    options.ALPNProtocols = ['http/1.1'];
  }

  const upstream = (secure ? https : http).request(options, (up) => {
    const out = {};
    for (const [k, v] of Object.entries(up.headers)) {
      if (!DROP_RES.has(k.toLowerCase())) out[k] = v;
    }
    out['x-accel-buffering'] = 'no';
    out['cache-control'] = 'no-store';
    res.writeHead(up.statusCode || 502, out);
    if (typeof res.flushHeaders === 'function') res.flushHeaders();
    up.on('data', (chunk) => { res.write(chunk); });
    up.on('end', () => res.end());
    up.on('error', () => { try { res.end(); } catch (_) {} });
  });
  upstream.setNoDelay(true);
  upstream.on('error', () => {
    if (!res.headersSent) { res.statusCode = 502; res.end('upstream unreachable'); } else { try { res.end(); } catch (_) {} }
  });
  res.on('close', () => { try { upstream.destroy(); } catch (_) {} });

  const method = (req.method || 'GET').toUpperCase();
  if (method === 'GET' || method === 'HEAD') {
    upstream.end();
  } else if (req.readableEnded) {
    const b = req.body;
    upstream.end(Buffer.isBuffer(b) || typeof b === 'string' ? b : undefined);
  } else {
    req.pipe(upstream);
  }
}
